#include "stdlib/lapack/base/dlaswp.h"
#include "stdlib/lapack/base/shared.h"
#include "stdlib/lapack/base/xerbla.h"

/**
* Performs a series of row interchanges on a matrix `A` using pivot indices stored in `IPIV`.
*
* @param layout  storage layout
* @param N       number of columns in `A`
* @param A       input matrix
* @param LDA     stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param k1      index of first row to interchange
* @param k2      index of last row to interchange
* @param IPIV    vector of pivot indices
* @param incx    increment between successive values of `IPIV`
*/
void API_SUFFIX(c_dlaswp)( const LAPACK_LAYOUT layout, const LAPACK_INT N, double *A, const LAPACK_INT LDA, const LAPACK_INT k1, const LAPACK_INT k2, const LAPACK_INT *IPIV, const LAPACK_INT incx ) {
	LAPACK_INT strideIPIV;
	LAPACK_INT offsetIPIV;
	LAPACK_INT sa1;
	LAPACK_INT sa2;
	LAPACK_INT ck1;
	LAPACK_INT ck2;
	LAPACK_INT inc;
	LAPACK_INT tmp;

	if ( layout != LAPACK_ROW_MAJOR && layout != LAPACK_COL_MAJOR ) {
		lapack_xerbla( "c_dlaswp", -1 );
		return;
	}
	ck1 = k1;
	ck2 = k2;
	if ( incx > 0 ) {
		inc = 1;
		offsetIPIV = ck1;
		strideIPIV = incx;
	} else if ( incx < 0 ) {
		inc = -1;
		offsetIPIV = ck1 + ( ( ck1 - ck2 ) * incx );
		strideIPIV = -incx;
		tmp = ck1;
		ck1 = ck2;
		ck2 = tmp;
	} else {
		return;
	}
	if ( layout == LAPACK_COL_MAJOR ) {
		sa1 = 1;
		sa2 = LDA;
	} else { // layout == LAPACK_ROW_MAJOR
		sa1 = LDA;
		sa2 = 1;
	}
	API_SUFFIX(c_dlaswp_ndarray)( N, A, sa1, sa2, 0, ck1, ck2, inc, IPIV, strideIPIV, offsetIPIV );
}
